import string

def caesar(s, shift):
    result = ''
    for ch in s:
        if ch.isalpha():
            # preserve case (though message is lowercase except first letters?)
            # Let's treat as uppercase base: compute shift 
            # We'll shift letters backward by shift (i.e., each letter replaced by the letter shift positions earlier in alphabet)
            # But for exploring all combos, we can shift forward.
            base = ord('A') if ch.isupper() else ord('a')
            # Let's shift forward by 'shift' (i.e., each letter replaced by letter shift positions later) - used for rotating.
            # Actually typical Caesar shift: new char = base + (ord(ch)-base + shift) % 26
            result += chr(base + (ord(ch) - base + shift) % 26)
        else:
            result += ch
    return result

